SELECT bdi.abbreviation, bdi.billDetailId, bdi.itemId, bdi.itemNum, bdi.itemName, bdi.itemType, bdi.categoryId, bdi.categoryName, bdi.billNum, DATE_FORMAT( bdi.orderDate, '%Y-%m-%d' ) as orderDate, bdi.patientId, bdi.patientName, bdi.mobile, bdi.gender, bdi.executorId, bdi.executorName, bdi.price, bdi.quantity, bdi.totalOriginalAmount, bdi.discountAmount, bdi.totalOriginalAmount - bdi.discountAmount AS actualAmount FROM ( SELECT bbd.org_id AS orgId, bo.abbreviation, bp.billId, bbd.bill_detail_id AS billDetailId, bbd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, bbd.item_type AS itemType, bti.category_id AS categoryId, bti.category_name AS categoryName, bp.billNum, bp.orderDate, bp.patientId, bp.patientName, bp.pinyinName, bp.mobile, bp.gender, bbd.executor_id AS executorId, be.employee_name AS executorName, bbd.price, bbd.quantity, bbd.price * bbd.quantity AS totalOriginalAmount, bbd.discount_amount AS discountAmount FROM base_bill_detail bbd LEFT JOIN base_tariff_info bti ON bbd.item_id=bti.item_id AND bbd.item_type=bti.item_type LEFT JOIN ( SELECT bb.bill_id AS billId, bb.order_date AS orderDate, bb.patient_id AS patientId, bb.bill_num AS billNum, bp.`name` AS patientName, bp.gender AS gender, bp.mobile AS mobile, bp.pinyin_name AS pinyinName FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bp ON bbd.bill_id = bp.billId LEFT JOIN base_employee be ON bbd.executor_id = be.user_id LEFT JOIN base_organization bo ON bo.org_id = bbd.org_id ) bdi
AND bdi.orgId in
#{item}
AND DATE_FORMAT(bdi.orderDate, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(bdi.orderDate, '%Y-%m') <= #{query.endDate}
AND concat(ifnull(bdi.patientName, ''), ifnull(bdi.pinyinName, ''), ifnull(bdi.mobile, '')) Like concat('%', #{query.keyWord}, '%')
ORDER BY bdi.orderDate DESC, bdi.billId DESC, bdi.billDetailId DESC

SELECT #{query.orgId} AS orgId, employeeId, employeeName, workStatus, baseWorkload, bonusCoefficient, postNames, actualWorkload, supplementWorkload, receivedWorkload, freePaymentWorkload, refundWorkload, processingFee, orthodonticsFee, largeMaterialCost FROM ( SELECT bup.user_id AS employeeId, bup.employee_name AS employeeName, bup.work_status AS workStatus, IFNULL( ewc.baseWorkload, 0 ) AS baseWorkload, IFNULL( bup.bonus_coefficient, 0 ) AS bonusCoefficient, bup.post_names AS postNames, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bbd1.supplementWorkload, 0 ) AS supplementWorkload, IFNULL( bbd2.receivedWorkload, 0 ) AS receivedWorkload, IFNULL( bbd3.freePaymentWorkload, 0 ) AS freePaymentWorkload, IFNULL( brd.refundWorkload, 0 ) AS refundWorkload, IFNULL( ewc.processingFee, 0 ) AS processingFee, IFNULL( ewc.orthodonticsFee, 0 ) AS orthodonticsFee, IFNULL( ewc.largeMaterialCost, 0 ) AS largeMaterialCost FROM ( SELECT be.user_id, be.employee_name, be.work_status, IFNULL( be.bonus_coefficient, 0 ) AS bonus_coefficient, GROUP_CONCAT( DISTINCT bup.post_name SEPARATOR ',' ) AS post_names FROM base_employee be INNER JOIN base_user_post bup ON be.user_id = bup.user_id
and bup.user_id in
#{item}
and be.work_status in
#{item}
and bup.post_id in
#{item}
GROUP BY bup.user_id ) bup LEFT JOIN ( SELECT bbd.executor_id, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS actualWorkload FROM ( SELECT bbd.executor_id, bbd.discount_amount, bbd.price, bbd.quantity FROM base_bill_detail bbd INNER JOIN base_bill bb ON bbd.bill_id = bb.bill_id
bbd.executor_id > 0 AND bb.bill_date IS NOT NULL
and bb.org_id = #{query.orgId}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}
) bbd GROUP BY bbd.executor_id ) bbd ON bup.user_id = bbd.executor_id LEFT JOIN ( SELECT bbd.executor_id, SUM(bbd.coupon_workload) AS supplementWorkload FROM ( SELECT bbd.executor_id, bbd.coupon_workload FROM base_bill_detail bbd INNER JOIN base_bill bb ON bbd.bill_id = bb.bill_id
bbd.executor_id > 0 AND bb.bill_date IS NOT NULL
and bb.org_id = #{query.orgId}
and DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( bb.privilege_date, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( bb.privilege_date, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( bb.privilege_date, '%Y' ) >= #{query.endDate}
and DATE_FORMAT( bb.privilege_date, '%Y' ) <= #{query.endDate}
) bbd GROUP BY bbd.executor_id ) bbd1 ON bup.user_id = bbd1.executor_id LEFT JOIN ( SELECT bbd.executor_id, CONVERT ( SUM( bbd.billWorkload / bbd.actualAmount * bbd.receivedAmount ), DECIMAL ( 19, 2 )) AS receivedWorkload FROM ( SELECT bbp.actualAmount, bbp.receivedAmount, bbd.billWorkload, bbd.executor_id FROM ( SELECT bb.bill_id AS billId, bb.actual_amount AS actualAmount, bbp.bill_pay_id AS billPayId, bbp.received_amount AS receivedAmount FROM base_bill_pay bbp INNER JOIN base_bill bb ON bbp.bill_id = bb.bill_id
AND bbp.received_amount > 0
AND DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payee_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y' ) <= #{query.endDate}
AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
) bbp INNER JOIN ( SELECT bbd.bill_id, bbd.executor_id, bbd.billWorkload FROM ( SELECT bbd.bill_id, bbd.executor_id, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS billWorkload FROM base_bill_detail bbd
AND bbd.executor_id > 0
AND bbd.org_id = #{query.orgId}
GROUP BY bbd.bill_id, bbd.executor_id ) bbd WHERE bbd.billWorkload > 0 ) bbd ON bbp.billId = bbd.bill_id ) bbd GROUP BY bbd.executor_id ) bbd2 ON bup.user_id = bbd2.executor_id LEFT JOIN ( SELECT bbd.executor_id, CONVERT ( SUM( bbd.billWorkload / bbd.billTotalWorkload * bbd.freePayAmount ), DECIMAL ( 19, 2 )) AS freePaymentWorkload FROM ( SELECT bbp.billTotalWorkload, IF ( bbp.freePayAmount > bbp.billTotalWorkload, bbp.billTotalWorkload, bbp.freePayAmount ) AS freePayAmount, bbd.billWorkload, bbd.executor_id FROM ( SELECT bbpd.bill_id, bbpd.bill_pay_id, SUM( bbpd.principal_amount ) AS freePayAmount, bbp.billTotalWorkload FROM base_bill_pay_detail bbpd INNER JOIN ( SELECT bbp.bill_pay_id, bbd.billTotalWorkload FROM base_bill_pay bbp INNER JOIN base_bill bb ON bbp.bill_id = bb.bill_id INNER JOIN ( SELECT bbd.bill_id, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS billTotalWorkload FROM base_bill_detail bbd
AND bbd.executor_id > 0
AND bbd.org_id = #{query.orgId}
GROUP BY bbd.bill_id ) bbd ON bbp.bill_id = bbd.bill_id
AND DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payee_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payee_date, '%Y' ) <= #{query.endDate}
AND bbp.received_amount > 0 AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
) bbp ON bbpd.bill_pay_id = bbp.bill_pay_id WHERE bbpd.account_item_id IN ( 23, 26 ) GROUP BY bbpd.bill_pay_id ) bbp INNER JOIN ( SELECT bbd.bill_id, bbd.executor_id, bbd.billWorkload FROM ( SELECT bbd.bill_id, bbd.executor_id, SUM( bbd.price * bbd.quantity - bbd.discount_amount ) AS billWorkload FROM base_bill_detail bbd
AND bbd.executor_id > 0
AND bbd.org_id = #{query.orgId}
GROUP BY bbd.bill_id, bbd.executor_id ) bbd WHERE bbd.billWorkload > 0 ) bbd ON bbp.bill_id = bbd.bill_id ) bbd GROUP BY bbd.executor_id ) bbd3 ON bup.user_id = bbd3.executor_id LEFT JOIN ( SELECT SUM( brd.refund_amount ) AS refundWorkload, brd.executor_id FROM ( SELECT brd.refund_amount, brd.executor_id FROM base_refund_detail brd INNER JOIN ( SELECT br.refund_id FROM base_refund br
and br.org_id = #{query.orgId}
and DATE_FORMAT( br.refund_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( br.refund_date, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( br.refund_date, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( br.refund_date, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( br.refund_date, '%Y' ) >= #{query.startDate}
and DATE_FORMAT( br.refund_date, '%Y' ) <= #{query.endDate}
) br ON brd.refund_id = br.refund_id ) brd WHERE brd.executor_id > 0 GROUP BY brd.executor_id ) brd ON bup.user_id = brd.executor_id LEFT JOIN ( SELECT ewc.user_id, SUM( ewc.processing_fee ) AS processingFee, SUM( ewc.orthodontics_fee ) AS orthodonticsFee, SUM( ewc.base_workload ) AS baseWorkload, SUM( ewc.material_fee ) AS largeMaterialCost FROM employee_workload_cost ewc
and ewc.org_id = #{query.orgId}
and DATE_FORMAT( ewc.entry_month, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( ewc.entry_month, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( ewc.entry_month, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( ewc.entry_month, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( ewc.entry_month, '%Y' ) >= #{query.startDate}
and DATE_FORMAT( ewc.entry_month, '%Y' ) <= #{query.endDate}
GROUP BY ewc.user_id ) ewc ON bup.user_id = ewc.user_id ) bup
bup.actualWorkload > 0 or bup.supplementWorkload > 0 or bup.receivedWorkload > 0 or bup.freePaymentWorkload > 0 or bup.refundWorkload > 0 or bup.processingFee > 0 or bup.orthodonticsFee > 0 or bup.baseWorkload > 0 or bup.largeMaterialCost > 0
ORDER BY bup.actualWorkload DESC, bup.receivedWorkload DESC, bup.supplementWorkload DESC, bup.freePaymentWorkload DESC, bup.refundWorkload DESC, bup.processingFee DESC, bup.orthodonticsFee DESC, bup.baseWorkload DESC, bup.largeMaterialCost DESC

