GROUP BY bbd.bill_id, bbd.executor_id ) bbd WHERE bbd.billWorkload > 0 ) bbd ON bbp.bill_id = bbd.bill_id ) bbd GROUP BY bbd.executor_id ) bbd3 ON bup.user_id = bbd3.executor_id LEFT JOIN ( SELECT SUM( brd.refund_amount ) AS refundWorkload, brd.executor_id, brd.org_id, brd.abbreviation FROM ( SELECT br.org_id, bo.abbreviation, br.refund_date, brd.refund_amount, brd.executor_id FROM base_refund_detail brd INNER JOIN base_refund br ON brd.refund_id = br.refund_id left JOIN base_organization bo ON br.org_id = bo.org_id ) brd
and brd.executor_id > 0
