GROUP BY brd.executor_id ) brd ON bup.user_id = brd.executor_id LEFT JOIN ( SELECT SUM( ewc.processing_fee ) AS processingFee, SUM( ewc.orthodontics_fee ) AS orthodonticsFee, SUM( ewc.base_workload ) AS baseWorkload, SUM( ewc.material_fee ) AS largeMaterialCost, ewc.user_id FROM employee_workload_cost ewc
