select bti.item_type as categoryType, bti.category_id as categoryId, sum(bbd.price * bbd.quantity) as totalOriginalAmount from base_bill_detail bbd left join base_tariff_info bti on bbd.item_id = bti.item_id and bbd.item_type = bti.item_type left join base_bill bb on bbd.bill_id = bb.bill_id
and bb.bill_date is not null
and bb.org_id = #{query.orgId}
and date_format(bb.bill_date, '%Y-%m') = #{query.queryDate}
group by bti.item_type, bti.category_id

select bdp.categoryId, bdp.itemType AS categoryType, bdp.categoryName, 0 AS totalOriginalAmount, 0 AS totalActualAmount, ifnull(sum(bdp.discountAmount),0) as totalDiscountAmount, ifnull(SUM(bdp.supplementWorkload),0) AS totalCouponAmount from ( select bti.item_type as itemType, bti.category_id as categoryId, bti.category_name as categoryName, bbd.discount_amount as discountAmount, bbd.price * bbd.quantity as totalOriginalAmount, bbd.coupon_workload AS supplementWorkload from base_bill_detail bbd left join base_tariff_info bti on bbd.item_id = bti.item_id and bbd.item_type = bti.item_type left join base_bill bb on bbd.bill_id = bb.bill_id
and bb.bill_date is not null
and bb.org_id = #{query.orgId}
and date_format(bb.bill_date, '%Y-%m') = #{query.queryDate} and date_format(bb.privilege_date, '%Y-%m') = #{query.queryDate}
order by bti.item_type, bti.category_id ) bdp group by bdp.itemType, bdp.categoryId

